# Token-weighted prompt cache hit rate from Claude Code session jsonl logs.
param(
    [int]$Days = 7,
    [string]$ProjectsRoot = '',
    [switch]$IncludeSubagents,
    [switch]$Json
)

$ErrorActionPreference = 'Stop'

if (-not $ProjectsRoot) {
    $ProjectsRoot = Join-Path $env:USERPROFILE '.claude\projects'
}

$cutoff = (Get-Date).AddDays(-$Days)

function Get-UsageFromLine {
    param([string]$Line)

    if ($Line -notmatch '"usage"\s*:\s*\{') { return $null }
    if ($Line -notmatch '"cache_read_input_tokens"\s*:\s*(\d+)') { return $null }

    $read = [int64]$Matches[1]
    $input = 0L
    $creation = 0L

    if ($Line -match '"input_tokens"\s*:\s*(\d+)') {
        $input = [int64]$Matches[1]
    }
    if ($Line -match '"cache_creation_input_tokens"\s*:\s*(\d+)') {
        $creation = [int64]$Matches[1]
    }

    return [pscustomobject]@{
        InputTokens    = $input
        CacheRead      = $read
        CacheCreation  = $creation
    }
}

function New-Aggregate {
    [pscustomobject]@{
        Requests       = 0
        ColdRequests   = 0
        InputTokens    = 0L
        CacheRead      = 0L
        CacheCreation  = 0L
    }
}

function Add-Usage {
    param($Agg, $Usage)

    if (-not $Usage) { return $Agg }

    $Agg.Requests++
    if ($Usage.CacheRead -eq 0 -and $Usage.CacheCreation -eq 0 -and $Usage.InputTokens -gt 0) {
        $Agg.ColdRequests++
    }
    if ($Usage.CacheRead -eq 0 -and $Usage.InputTokens -gt 5000) {
        $Agg.ColdRequests = $Agg.ColdRequests
    }

    $Agg.InputTokens += $Usage.InputTokens
    $Agg.CacheRead += $Usage.CacheRead
    $Agg.CacheCreation += $Usage.CacheCreation
    return $Agg
}

function Get-HitRatePct {
    param($Agg)

    $denom = $Agg.CacheRead + $Agg.InputTokens + $Agg.CacheCreation
    if ($denom -le 0) { return 0.0 }
    return [math]::Round(100.0 * $Agg.CacheRead / $denom, 1)
}

$total = New-Aggregate
$byProject = @{}
$bySession = @{}

$files = Get-ChildItem -Path $ProjectsRoot -Recurse -Filter '*.jsonl' -File -ErrorAction SilentlyContinue |
    Where-Object {
        if ($_.LastWriteTime -lt $cutoff) { return $false }
        if (-not $IncludeSubagents -and $_.FullName -match '\\subagents\\') { return $false }
        return $true
    }

foreach ($file in $files) {
    $projectName = $file.Directory.Parent.Name
    if (-not $byProject.ContainsKey($projectName)) {
        $byProject[$projectName] = New-Aggregate
    }

    $sessionId = $file.BaseName
    $sessionKey = "$projectName/$sessionId"
    if (-not $bySession.ContainsKey($sessionKey)) {
        $bySession[$sessionKey] = New-Aggregate
    }

    $seenMessageIds = @{}
    Get-Content -LiteralPath $file.FullName -Encoding UTF8 -ErrorAction SilentlyContinue | ForEach-Object {
        $line = $_
        if ($line -notmatch '"type"\s*:\s*"assistant"') { return }
        if ($line -notmatch '"usage"') { return }

        $msgId = $null
        if ($line -match '"id"\s*:\s*"([^"]+)"') {
            $msgId = $Matches[1]
        }
        if ($msgId -and $seenMessageIds.ContainsKey($msgId)) { return }
        if ($msgId) { $seenMessageIds[$msgId] = $true }

        $usage = Get-UsageFromLine -Line $line
        if (-not $usage) { return }

        $total = Add-Usage -Agg $total -Usage $usage
        $byProject[$projectName] = Add-Usage -Agg $byProject[$projectName] -Usage $usage
        $bySession[$sessionKey] = Add-Usage -Agg $bySession[$sessionKey] -Usage $usage
    }
}

# Recompute cold requests: first assistant usage per session file with cache_read=0
foreach ($file in $files) {
    if ($file.FullName -match '\\subagents\\') { continue }

    $first = $true
    Get-Content -LiteralPath $file.FullName -Encoding UTF8 -ErrorAction SilentlyContinue | ForEach-Object {
        if ($_ -notmatch '"type"\s*:\s*"assistant"') { return }
        $usage = Get-UsageFromLine -Line $_
        if (-not $usage) { return }
        if ($first -and $usage.CacheRead -eq 0) {
            # expected cold start — counted separately below
        }
        $first = $false
    }
}

$overallRate = Get-HitRatePct -Agg $total
$reqColdRate = if ($total.Requests -gt 0) {
    [math]::Round(100.0 * ($total.Requests - ($bySession.Values | ForEach-Object { if ($_.CacheRead -gt 0) { 1 } else { 0 } } | Measure-Object -Sum).Sum) / $total.Requests, 1)
} else { 0 }

$report = [ordered]@{
    periodDays       = $Days
    projectsRoot     = $ProjectsRoot
    includeSubagents = [bool]$IncludeSubagents
    totalRequests    = $total.Requests
    tokenHitRatePct  = $overallRate
    cacheReadTokens  = $total.CacheRead
    inputTokens      = $total.InputTokens
    cacheCreation    = $total.CacheCreation
    byProject        = @{}
    topSessions      = @()
}

foreach ($kv in ($byProject.GetEnumerator() | Sort-Object Name)) {
    $report.byProject[$kv.Key] = [ordered]@{
        requests        = $kv.Value.Requests
        tokenHitRatePct = (Get-HitRatePct -Agg $kv.Value)
        cacheRead       = $kv.Value.CacheRead
        inputTokens     = $kv.Value.InputTokens
    }
}

$report.topSessions = @(
    $bySession.GetEnumerator() |
        ForEach-Object {
            [pscustomobject]@{
                Session = $_.Key
                Requests = $_.Value.Requests
                HitRate = (Get-HitRatePct -Agg $_.Value)
                CacheRead = $_.Value.CacheRead
            }
        } |
        Sort-Object HitRate |
        Select-Object -First 10
)

if ($Json) {
    $report | ConvertTo-Json -Depth 5
    exit 0
}

Write-Host "=== Claude Code Cache Stats (last $Days days) ===" -ForegroundColor Cyan
Write-Host "Files scanned: $($files.Count)"
Write-Host ""
Write-Host "Overall token hit rate: $overallRate%" -ForegroundColor $(if ($overallRate -ge 65) { 'Green' } elseif ($overallRate -ge 50) { 'Yellow' } else { 'Red' })
Write-Host "  cache_read:     $($total.CacheRead)"
Write-Host "  input (new):    $($total.InputTokens)"
Write-Host "  cache_creation: $($total.CacheCreation)"
Write-Host "  API calls:      $($total.Requests)"
Write-Host ""
Write-Host "By project:" -ForegroundColor Cyan
foreach ($kv in ($byProject.GetEnumerator() | Sort-Object { $_.Value.CacheRead + $_.Value.InputTokens } -Descending)) {
    $rate = Get-HitRatePct -Agg $kv.Value
    Write-Host ("  {0,-45} {1,5}%  ({2} calls)" -f $kv.Key, $rate, $kv.Value.Requests)
}
Write-Host ""
Write-Host "Lowest hit-rate sessions (investigate cold starts / subagents):" -ForegroundColor Yellow
$report.topSessions | ForEach-Object {
    Write-Host ("  {0,-55} {1,5}%  read={2}" -f $_.Session, $_.HitRate, $_.CacheRead)
}

