    param(
        [array]$Items,
        [array]$AlwaysOnItems,
        [string]$ProjectMemoryOverlay,
        [object]$CodingGuardrails = $null
    )

    $mem = Get-GlobalMemoryPaths
    $lines = @(
        '## Global Skills (SessionStart)',
        '',
