function logCacheFromUsage(usage, model) {
  if (!usage) return;
  const hit =
    usage.prompt_cache_hit_tokens ??
    usage.cache_read_input_tokens ??
    0;
  const miss =
    usage.prompt_cache_miss_tokens ??
    usage.input_tokens ??
    0;
  const creation =
    usage.cache_creation_input_tokens ??
    usage.prompt_cache_creation_tokens ??
    0;
  if (hit || miss || creation) {
    const modelTag = model ? ` model=${model}` : "";
    appendLog(
      `cache hit=${hit} miss=${miss} creation=${creation}${modelTag}`
    );
  }
}

function logCacheFromBody(body) {
  try {
    const parsed = JSON.parse(body);
    logCacheFromUsage(parsed?.usage, parsed?.model);
  } catch {
    /* ignore */
  }
}

function extractUsageFromSseBuffer(buffer) {
  let lastUsage = null;
  let lastModel = null;
  const lines = buffer.split("\n");
  for (const line of lines) {
    if (!line.startsWith("data:")) continue;
    const payload = line.slice(5).trim();
    if (!payload || payload === "[DONE]") continue;
    try {
      const evt = JSON.parse(payload);
      if (evt?.message?.model) lastModel = evt.message.model;
      if (evt?.model) lastModel = evt.model;
      const usage =
        evt?.usage ??
        evt?.message?.usage ??
        (evt?.type === "message_delta" ? evt.usage : null);
      if (usage) lastUsage = usage;
    } catch {
      /* ignore partial JSON */
    }
  }
  if (lastUsage) logCacheFromUsage(lastUsage, lastModel);
}

function forward(req, res, body) {
  let outBody = body;
  let requestModel = null;
  if (
    req.method === "POST" &&
    (req.url?.includes("/messages") || req.url?.includes("/complete"))
  ) {
    try {
      const parsed = JSON.parse(body);
      requestModel = parsed?.model ?? null;
      outBody = fixAnthropicBody(body);
    } catch {
      outBody = body;
    }
  }

  const headers = { ...req.headers, host: TARGET_HOST };
  delete headers["content-length"];
  headers["content-length"] = Buffer.byteLength(outBody);

  const urlPath = req.url?.startsWith("/anthropic")
    ? req.url
    : `/anthropic${req.url || ""}`;

  const upstream = https.request(
    {
      hostname: TARGET_HOST,
      port: 443,
      path: urlPath,
      method: req.method,
      headers,
    },
    (pres) => {
      const isStream =
        pres.headers["content-type"]?.includes("text/event-stream") ||
        outBody.includes('"stream":true') ||
        outBody.includes('"stream": true');

      if (isStream) {
        res.writeHead(pres.statusCode ?? 502, pres.headers);
        let sseBuffer = "";
        pres.on("data", (chunk) => {
          res.write(chunk);
          sseBuffer += chunk.toString("utf8");
          if (sseBuffer.length > 512_000) {
            sseBuffer = sseBuffer.slice(-256_000);
          }
        });
        pres.on("end", () => {
          extractUsageFromSseBuffer(sseBuffer);
          res.end();
        });
        return;
      }

      const chunks = [];
      pres.on("data", (c) => chunks.push(c));
      pres.on("end", () => {
        const respBody = Buffer.concat(chunks).toString("utf8");
        logCacheFromBody(respBody);
        res.writeHead(pres.statusCode ?? 502, pres.headers);
        res.end(respBody);
      });
    }
  );

