    [double]$MinHitRatePct = 75.0
)

$ErrorActionPreference = 'Stop'

if (-not $SessionFile) {
    $root = Join-Path $env:USERPROFILE '.claude\projects\c--Users-win-Desktop-program1-main'
    $SessionFile = Get-ChildItem -Path $root -Filter '*.jsonl' -File |
