function Get-UsageFromLine {
    param([string]$Line)
    if ($Line -notmatch '"type"\s*:\s*"assistant"') { return $null }
    if ($Line -notmatch '"cache_read_input_tokens"\s*:\s*(\d+)') { return $null }
    $read = [int64]$Matches[1]
    $input = 0L
    $creation = 0L
    if ($Line -match '"input_tokens"\s*:\s*(\d+)') { $input = [int64]$Matches[1] }
    if ($Line -match '"cache_creation_input_tokens"\s*:\s*(\d+)') { $creation = [int64]$Matches[1] }
    return [pscustomobject]@{ Input = $input; Read = $read; Creation = $creation }
}

$usages = @()
$seenIds = @{}
Get-Content -LiteralPath $SessionFile -Encoding UTF8 | ForEach-Object {
    $line = $_
    if ($line -notmatch '"id"\s*:\s*"([^"]+)"') { return }
    $id = $Matches[1]
    if ($seenIds.ContainsKey($id)) { return }
    $u = Get-UsageFromLine -Line $line
    if (-not $u) { return }
    $seenIds[$id] = $true
    $usages += $u
}

$allRead = ($usages | Measure-Object -Property Read -Sum).Sum
$allInput = ($usages | Measure-Object -Property Input -Sum).Sum
$allCreation = ($usages | Measure-Object -Property Creation -Sum).Sum
$allDenom = $allRead + $allInput + $allCreation
$allRate = if ($allDenom -gt 0) { [math]::Round(100.0 * $allRead / $allDenom, 1) } else { 0 }

$warm = @($usages | Select-Object -Skip $SkipFirstCold)
$warmRead = ($warm | Measure-Object -Property Read -Sum).Sum
$warmInput = ($warm | Measure-Object -Property Input -Sum).Sum
$warmCreation = ($warm | Measure-Object -Property Creation -Sum).Sum
$warmDenom = $warmRead + $warmInput + $warmCreation
$warmRate = if ($warmDenom -gt 0) { [math]::Round(100.0 * $warmRead / $warmDenom, 1) } else { 0 }

Write-Host "=== Session cache verify ===" -ForegroundColor Cyan
Write-Host "File: $SessionFile"
Write-Host "Calls: $($usages.Count) (warm subset: $($warm.Count), skip first $SkipFirstCold)"
Write-Host ""
Write-Host ("All calls token hit rate:     {0}%" -f $allRate)
Write-Host ("Warm calls token hit rate:    {0}%" -f $warmRate) -ForegroundColor $(if ($warmRate -ge $MinHitRatePct) { 'Green' } else { 'Yellow' })
Write-Host ""
Write-Host "  cache_read total:    $allRead"
Write-Host "  input (new) total:   $allInput"
Write-Host "  cache_creation:      $allCreation"

if ($warmRate -ge $MinHitRatePct) {
    Write-Host ""
    Write-Host "PASS warm hit rate >= $MinHitRatePct%" -ForegroundColor Green
    exit 0
}

Write-Host ""
Write-Host "WARN warm hit rate < $MinHitRatePct% (check cold starts, MCP churn, model switch)" -ForegroundColor Yellow
exit 1

